import numpy as np, json

lines = open('initial.xyz').read().strip().split('\n')
n = int(lines[0])
P = np.array([list(map(float,l.split()[1:4])) for l in lines[2:2+n]])
els = [l.split()[0] for l in lines[2:2+n]]
names = open('names.txt').read().split()

def tag_of(nm):
    for t in ['A1','A2','B1','B2']:
        if nm.startswith('Mes') and nm.endswith(t): return 'Mes'+t
    for t in ['A','B']:
        if nm.startswith('Cp') and nm.endswith(t): return 'Cp'+t
    return None

groups = {}
for i,nm in enumerate(names):
    t = tag_of(nm)
    if t: groups.setdefault(t, []).append(i)

axes = {}
idx = {nm:i for i,nm in enumerate(names)}
for t in ['MesA1','MesA2','MesB1','MesB2']:
    N = 'N1' if t.endswith('1') else 'N2'
    N += 'A' if 'A' in t[3] else 'B'
    axes[t] = (idx[N], idx['MesIpo'+t[3:]])
for t in ['CpA','CpB']:
    cs = [idx['CpC%d%s'%(k,t[2])] for k in range(5)]
    G = P[cs].mean(axis=0)
    axes[t] = (idx['Zn'+t[2]], None, G)

group_of = {}
for t,mem in groups.items():
    for i in mem: group_of[i]=t

def min_inter(P):
    D = np.linalg.norm(P[:,None]-P[None],axis=-1)
    best = 99
    for i in range(n):
        gi = group_of.get(i)
        for j in range(i+1,n):
            gj = group_of.get(j)
            if gi is not None and gi==gj: continue
            if D[i,j]<best: best=D[i,j]
    return best

def rotate_group(P, t, ang):
    P = P.copy()
    mem = groups[t]
    if t.startswith('Mes'):
        a,b = axes[t]; origin = P[a]; axis = P[b]-P[a]
    else:
        a,_,G = axes[t]; origin = P[a]; axis = G-P[a]
    axis = axis/np.linalg.norm(axis)
    c,s = np.cos(np.radians(ang)), np.sin(np.radians(ang))
    R = c*np.eye(3) + s*np.array([[0,-axis[2],axis[1]],[axis[2],0,-axis[0]],[-axis[1],axis[0],0]]) + (1-c)*np.outer(axis,axis)
    P[mem] = (R@(P[mem]-origin).T).T + origin
    return P

order = ['MesA1','MesA2','MesB1','MesB2','CpA','CpB']
for sweep in range(4):
    for t in order:
        bestang, bestv = 0, min_inter(P)
        for ang in range(-90,91,10):
            if ang==0: continue
            v = min_inter(rotate_group(P,t,ang))
            if v>bestv: bestv, bestang = v, ang
        if bestang: P = rotate_group(P,t,bestang)
    print("sweep",sweep,"min inter:", round(min_inter(P),3))

with open('initial2.xyz','w') as f:
    f.write("%d\nbuilt dimer clash-relaxed\n"%n)
    for i in range(n):
        f.write("%s %.6f %.6f %.6f\n"%(els[i],P[i,0],P[i,1],P[i,2]))
